      "matched_intervention": "Matched intervention",
      "mystery_prize": "Mystery Prize",
      "next_vignette": "Next vignette →",
      "on_task_15_min": "On-task 15 min",
      "pick_the_function": "Pick the function",
      "quiet_transition": "Quiet Transition",
